let ownPlaylists=[];try{ownPlaylists=JSON.parse(localStorage.getItem('soulroom.playlists'))||[]}catch{}if(!Array.isArray(ownPlaylists))ownPlaylists=[];
let favoriteMode='tracks',playlistSelected=null,playlistBusy=false,playlistNotice='',remotePlaylists=[];
function persistPlaylists(){localStorage.setItem('soulroom.playlists',JSON.stringify(ownPlaylists));saveRemote()}
function createPlaylist(title,items=[],source='soulroom'){const p={id:crypto.randomUUID(),title:String(title||'Новый плейлист').trim().slice(0,100),source,items:[...new Map(items.filter(t=>t?.id&&t?.title).map(t=>[t.id,t])).values()],createdAt:Date.now()};ownPlaylists.push(p);persistPlaylists();return p}
function playlistScreen(){const p=ownPlaylists.find(x=>x.id===playlistSelected);return heading(p?p.title:'Твои плейлисты.',p?`${p.items.length} треков · ${serviceNames[p.source]||'soulroom'}`:'Собери своё. Забери любимое с собой.')+`<div class="playlist-actions"><button class="primary" id="newPlaylist">${playerIcon('plus')}Создать плейлист</button><button class="secondary" id="openPlaylistImport">Перенести из сервиса</button>${p?'<button class="secondary" id="allPlaylists">Все плейлисты</button><button class="secondary" id="renamePlaylist">Переименовать</button><button class="secondary" id="addPlayingPlaylist">Добавить текущий трек</button>':''}</div>${p?`<div id="playlistTracks">${p.items.length?p.items.map((t,i)=>'<div class="playlist-track">'+row(t,i)+'<button data-remove-playlist-track="'+esc(t.id)+'" aria-label="Убрать из плейлиста">×</button></div>').join(''):'<div class="empty"><h2>Тут начнётся твоя история</h2><p>Добавляй песни через меню трека или кнопку «Добавить текущий трек».</p></div>'}</div>`:`<div class="playlist-grid">${ownPlaylists.map(p=>`<button class="playlist-card" data-open-playlist="${esc(p.id)}"><div class="playlist-mosaic">${p.items.slice(0,4).map(t=>`<img src="${esc(coverSource(t.cover,image(0)))}" alt="">`).join('')||playerIcon('library')}</div><strong>${esc(p.title)}</strong><span>${p.items.length} треков · ${serviceNames[p.source]||'soulroom'}</span></button>`).join('')||'<div class="empty"><h2>Место для твоих подборок</h2><p>Создай первый плейлист или перенеси его из подключённого сервиса.</p></div>'}</div>`}`}
const favoritesWithoutPlaylists=favoritesScreen;favoritesScreen=function(){return `<div class="favorite-sections"><button data-favorite-mode="tracks" class="${favoriteMode==='tracks'?'selected':''}">Любимые треки</button><button data-favorite-mode="playlists" class="${favoriteMode==='playlists'?'selected':''}">Плейлисты <span>${ownPlaylists.length}</span></button></div>`+(favoriteMode==='playlists'?playlistScreen():favoritesWithoutPlaylists())};
const findWithoutPlaylists=find;find=function(id){return findWithoutPlaylists(id)||ownPlaylists.flatMap(p=>p.items).find(t=>t.id===id)};
const playlistDialog=document.createElement('dialog');playlistDialog.className='quick-dialog playlist-dialog';playlistDialog.setAttribute('aria-label','Плейлисты');document.body.append(playlistDialog);
function playlistForm(kind,trackId){playlistDialog.innerHTML=`<div class="quick-dialog-head"><span class="eyebrow">ТВОЯ КОЛЛЕКЦИЯ</span><button data-close-playlist aria-label="Закрыть">×</button></div>`+(kind==='import'?`<h2>Всё любимое — с тобой.</h2><p>Перенеси копию плейлиста в soulroom. Оригинал останется в сервисе.</p><div class="playlist-service-buttons">${favoriteSources.map(s=>`<button class="secondary" data-list-remote-playlists="${s}" ${!backend?'disabled':''}>${serviceNames[s]}</button>`).join('')}</div><form id="playlistLinkForm"><label for="playlistUrl">Или вставь ссылку на плейлист</label><input id="playlistUrl" type="url" placeholder="https://…" required><button class="primary" ${!backend?'disabled':''}>Перенести по ссылке</button></form><p id="playlistImportStatus" role="status">${esc(playlistNotice)}</p><div id="remotePlaylistList"></div><small>До 300 треков. Для закрытых плейлистов нужен вход. Доступность аудио зависит от источника. Spotify может потребовать повторный вход с правом чтения плейлистов.</small>`:kind==='pick'?`<h2>В какой плейлист?</h2><div class="playlist-pick">${ownPlaylists.map(p=>`<button class="secondary" data-put-playlist="${esc(p.id)}" data-put-track="${esc(trackId)}">${esc(p.title)} <span>${p.items.length}</span></button>`).join('')||'<p>Сначала создай плейлист во вкладке «Любимое».</p>'}</div>`:`<h2>${kind==='rename'?'Название плейлиста':'Новая история.'}</h2><form id="playlistNameForm" data-kind="${kind}"><label for="playlistName">Название</label><input id="playlistName" maxlength="100" required value="${kind==='rename'?esc(ownPlaylists.find(p=>p.id===playlistSelected)?.title||''):''}" placeholder="Например, дорога домой"><button class="primary">Сохранить</button></form>`);if(!playlistDialog.open)playlistDialog.showModal();playlistDialog.querySelector('input,button')?.focus()}
function playlistAdd(p,t){if(!t)return;if(p.items.some(x=>x.id===t.id)){toast('Трек уже в плейлисте');return}p.items.push(t);persistPlaylists();toast('Добавлено в «'+p.title+'»');if(page==='favorites')renderFavorites()}
function importResult(d,title){if(d.error||d.reason)throw Error(d.message||'Не удалось получить плейлист: '+(d.error||d.reason));if(!d.items?.length)throw Error('Плейлист пуст или сервис не разрешил чтение.');const p=createPlaylist(title||d.title,d.items,d.source);playlistSelected=p.id;favoriteMode='playlists';playlistDialog.close();go('favorites');toast('Перенесено треков: '+p.items.length)}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.favoriteMode){favoriteMode=b.dataset.favoriteMode;renderFavorites()}if(b.dataset.openPlaylist){playlistSelected=b.dataset.openPlaylist;renderFavorites()}if(b.id==='allPlaylists'){playlistSelected=null;renderFavorites()}if(b.id==='newPlaylist')playlistForm('new');if(b.id==='renamePlaylist')playlistForm('rename');if(b.id==='openPlaylistImport')playlistForm('import');if(b.hasAttribute('data-close-playlist'))playlistDialog.close();if(b.id==='addPlayingPlaylist'){const p=ownPlaylists.find(p=>p.id===playlistSelected);if(current&&p)playlistAdd(p,current);else toast('Сначала выбери трек')}if(b.dataset.putPlaylist){const p=ownPlaylists.find(p=>p.id===b.dataset.putPlaylist);if(p)playlistAdd(p,find(b.dataset.putTrack));playlistDialog.close()}if(b.dataset.removePlaylistTrack){const p=ownPlaylists.find(p=>p.id===playlistSelected);if(p){p.items=p.items.filter(t=>t.id!==b.dataset.removePlaylistTrack);persistPlaylists();renderFavorites()}}
if(b.dataset.listRemotePlaylists){b.disabled=true;const source=b.dataset.listRemotePlaylists;$('#playlistImportStatus').textContent='Загружаем твои плейлисты…';try{const d=await api('playlists/'+source);if(d.error)throw Error(d.message||'Войди в аккаунт сервиса');remotePlaylists=(d.items||[]).map(p=>({...p,source}));$('#remotePlaylistList').innerHTML=remotePlaylists.map((p,i)=>`<button data-copy-remote-playlist="${i}"><span>${esc(p.title)}<small>${p.trackCount||0} треков</small></span>${playerIcon('plus')}</button>`).join('');$('#playlistImportStatus').textContent=remotePlaylists.length?'Выбери плейлист для переноса':'Сервис не вернул плейлистов.'}catch(e){$('#playlistImportStatus').textContent=e.message}finally{b.disabled=false}}
if(b.dataset.copyRemotePlaylist!==undefined&&!playlistBusy){const p=remotePlaylists[+b.dataset.copyRemotePlaylist];if(!p)return;playlistBusy=true;b.disabled=true;$('#playlistImportStatus').textContent='Переносим треки…';try{const d=await api(`playlists/${p.source}/${encodeURIComponent(p.id)}`);importResult({...d,source:p.source},p.title)}catch(e){$('#playlistImportStatus').textContent=e.message}finally{playlistBusy=false;b.disabled=false}}});
document.addEventListener('click',e=>{const item=e.target.closest('#playlistTracks [data-track]');if(!item||e.target.closest('[data-like],[data-track-actions],[data-open-track]'))return;e.stopImmediatePropagation();const p=ownPlaylists.find(p=>p.id===playlistSelected);if(p){queue=p.items.filter(t=>t.playable!==false);const t=find(item.dataset.track);if(t?.playable!==false)play(t);else toast('У трека нет доступного аудио. Найди версию в другом источнике.')}},true);
document.addEventListener('submit',async e=>{if(e.target.id==='playlistNameForm'){e.preventDefault();const title=$('#playlistName').value.trim();if(!title)return;if(e.target.dataset.kind==='rename'){const p=ownPlaylists.find(p=>p.id===playlistSelected);if(p)p.title=title;persistPlaylists()}else playlistSelected=createPlaylist(title).id;favoriteMode='playlists';playlistDialog.close();go('favorites')}if(e.target.id==='playlistLinkForm'){e.preventDefault();if(playlistBusy)return;playlistBusy=true;$('#playlistImportStatus').textContent='Переносим треки…';try{const d=await api('playlists/import',{method:'POST',body:JSON.stringify({url:$('#playlistUrl').value})});importResult(d)}catch(e){$('#playlistImportStatus').textContent=e.message}finally{playlistBusy=false}}});
playlistDialog.addEventListener('keydown',e=>{if(e.key==='Escape')e.stopPropagation()});
document.addEventListener('click',e=>{const b=e.target.closest('[data-add-to-playlist]');if(b){closeTrackActions();playlistForm('pick',b.dataset.addToPlaylist)}});
